      ro: ["Locația Budva", "Turism", "Funcționare sezonieră", "Port de iahturi"],
      en: ["Budva location", "Tourism", "Seasonal operation", "Marina"],
      es: ["Ubicación en Budva", "Turismo", "Funcionamiento estacional", "Puerto deportivo"],
